      { title: 'Адаптер оборачивает и сторонние SDK', text: 'Компоненты зависят от своего интерфейса, а не от API Метрики.', code: `export const analytics: Analytics = {
  track: (event, params) => ym(COUNTER_ID, 'reachGoal', event, params)
}`, lang: 'ts' },
      { title: 'Adapter vs Facade, Decorator, Proxy', text: 'Адаптер меняет форму интерфейса на ожидаемую. Фасад прячет подсистему из нескольких частей за простым входом. Декоратор и прокси интерфейс сохраняют: первый добавляет поведение, второй контролирует доступ.' }
